00:00"}, {"id": "db2c68ce-544b-46e9-9d37-459313a743aa", "question_key": "ask_vendor_investor_types", "dimension": "vendor_investor_types", "question_text": "What types of investors do you typically work with — flippers, buy and hold, wholesalers, commercial, or a mix?", "follow_up_text": "And are you mainly focused on residential or do you work on commercial deals too?", "applies_to_stages": null, "priority": 4, "path": "V", "is_active": true, "created_at": "2026-06-10T19:36:59.083088+00:00"}, {"id": "64963b4e-5c21-46cf-821b-b7b41bbaf0b5", "question_key": "ask_vendor_market", "dimension": "vendor_market", "question_text": "What areas or markets do you primarily serve — is it mostly Utah or do you work in other states too?", "follow_up_text": "And within Utah, are you focused on a specific area like Salt Lake, Utah County, or statewide?", "applies_to_stages": null, "priority": 5, "path": "V", "is_active": true, "created_at": "2026-06-10T19:36:59.083088+00:00"}, {"id": "dfbb701b-5ac1-477a-80d2-b645f819e34b", "question_key": "ask_vendor_reia_connection", "dimension": "vendor_reia_connection", "question_text": "Are you already connected with Utah REIA or is this your first time reaching out?", "follow_up_text": "Have you attended any of our events or worked with any of our members before?", "applies_to_stages": null, "priority": 6, "path": "V", "is_active": true, "created_at": "2026-06-10T19:36:59.083088+00:00"}, {"id": "d190194f-cbbd-4485-82fa-025cb0d4a76a", "question_key": "ask_vendor_enrollment_interest", "dimension": "vendor_enrollment_interest", "question_text": "We have a vendor directory where investors actively look for service providers like you. Would you like to get listed so members can find you directly?", "follow_up_text": "It gives you visibility with over 8,600 investors in our community. Is that something you would want?", "applies_to_stages": null, "priority": 7, "path": "V", "is_active": true, "created_at": "2026-06-10T19:36:59.083088+00:00"}, {"id": "fbb349b8-4658-4e0d-8cd2-282827a74ea2", "question_key": "ask_blocker_general", "dimension": "blocker", "question_text": "What is the main thing holding you back right now?", "follow_up_text": "Is it more of a knowledge gap, a capital problem, finding deals, or building your team?", "applies_to_stages": ["exploring__new", "getting_started", "active_investor", "experienced_investor", "veteran__operator"], "priority": 4, "path": "both", "is_active": true, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "2d35b602-6eda-40c2-ba39-1d3fd75792ca", "question_key": "ask_specific_need", "dimension": "specific_need", "question_text": "What specifically do you need right now?", "follow_up_text": "Is there a particular vendor, resource, or connection that would move the needle most?", "applies_to_stages": ["active_investor", "experienced_investor", "veteran__operator"], "priority": 1, "path": "both", "is_active": true, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "50467799-d477-4739-b5ed-5e9bd07fd472", "question_key": "ask_goal_active", "dimension": "goal", "question_text": "What are you trying to accomplish right now — more deals, better systems, capital, or something else?", "follow_up_text": "Is that the main focus or is there something else underneath it?", "applies_to_stages": ["active_investor", "experienced_investor", "veteran__operator"], "priority": 3, "path": "both", "is_active": true, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "fae0265a-459e-420f-b00e-97d7428c7ab5", "question_key": "ask_timeline", "dimension": "readiness", "question_text": "When are you hoping to do your first deal, or your next one: in the next ninety days, this year, or further out?", "follow_up_text": "What would need to happen for that timeline to feel realistic?", "applies_to_stages": null, "priority": 15, "path": "both", "is_active": false, "created_at": "2026-06-10T00:24:08.557193+00:00"}, {"id": "e819bb98-6bb0-43f8-aa61-99c903dbe5e9", "question_key": "ask_already_tried", "dimension": "already_tried", "question_text": "What steps have you actually taken so far, like analyzing deals, making offers, or reaching out to sellers or lenders?", "follow_up_text": "And how did that go?", "applies_to_stages": null, "priority": 8, "path": "both", "is_active": true, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "48e336f7-16ea-469b-958e-372d9b49829a", "question_key": "ask_support_network", "dimension": "resources", "question_text": "Do you have anyone in your corner already, like a lender, an agent, a contractor, or are you building your team from scratch?", "follow_up_text": "Who would you add first if you could?", "applies_to_stages": ["getting_started", "active_investor"], "priority": 14, "path": "both", "is_active": true, "created_at": "2026-06-10T00:24:08.557193+00:00"}, {"id": "012fa968-c6e6-44e4-8eac-ce55e219bbb2", "question_key": "ask_strategy_active", "dimension": "strategy", "question_text": "Are you investing actively, running deals yourself, or more passively, putting money into deals other people run?", "follow_up_text": "Got it. And which strategy specifically? Buy and hold, fix and flip, wholesale, commercial, notes, or something else?", "applies_to_stages": ["active_investor", "experienced_investor", "veteran__operator"], "priority": 2, "path": "both", "is_active": true, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "5dcd332e-afa3-47b7-b388-af49f25c0e8a", "question_key": "ask_goal_exploring", "dimension": "goal", "question_text": "What would success look like for you in the next six to twelve months?", "follow_up_text": "Is that more about learning and getting clarity, or actually closing a deal?", "applies_to_stages": ["exploring__new", "getting_started"], "priority": 3, "path": "A", "is_active": true, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "0cb02a2c-1bbf-4f2b-88fe-1685d71a9816", "question_key": "ask_resource_preference", "dimension": "learning_format", "question_text": "Are you looking more for one-on-one guidance, group learning, or specific tools and calculators?", "follow_up_text": "Have you worked with a mentor or coach before in any area?", "applies_to_stages": ["exploring__new", "getting_started"], "priority": 8, "path": "A", "is_active": true, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "66a11d32-8110-4a1c-967b-5abcab5c814b", "question_key": "ask_vendor_investor_primary_need", "dimension": "vendor_investor_primary_need", "question_text": "Since you are both an investor and a service provider, what is the main reason you called today — are you looking for resources for your own investing, or are you more focused on connecting with investors who need your services?", "follow_up_text": "We can help with both — just want to make sure I focus on the most useful thing first.", "applies_to_stages": null, "priority": 3, "path": "V", "is_active": true, "created_at": "2026-06-10T19:36:59.083088+00:00"}, {"id": "77295301-a549-4ca9-87fb-981f32bb9ec7", "question_key": "ask_vendor_follow_up_preference", "dimension": "vendor_follow_up_preference", "question_text": "The best next step is to get you enrolled and have someone from our team reach out. Would you prefer they contact you by phone or text?", "follow_up_text": "And is the number you called from the best one to reach you on?", "applies_to_stages": null, "priority": 8, "path": "V", "is_active": true, "created_at": "2026-06-10T19:36:59.083088+00:00"}, {"id": "d6b41939-f8fa-4cb5-b8c7-9605391610b0", "question_key": "ask_deal_count", "dimension": "deal_count", "question_text": "Roughly how many deals have you done with that strategy so far?", "follow_up_text": "A rough number is fine, just an estimate.", "applies_to_stages": ["active_investor", "experienced_investor", "veteran__operator"], "priority": 3, "path": "both", "is_active": true, "created_at": "2026-08-05T00:16:40.700045+00:00"}, {"id": "04cfd383-67a7-45cf-b1a3-3a5cca82d451", "question_key": "ask_education_history", "dimension": "education_history", "question_text": "On the learning side, what have you picked up so far: books, courses, a mentor, events, or is this still pretty new territory?", "follow_up_text": "Which of those was most helpful for you?", "applies_to_stages": ["exploring__new", "getting_started", "active_investor", "experienced_investor", "veteran__operator"], "priority": 12, "path": "both", "is_active": true, "created_at": "2026-06-10T00:24:08.557193+00:00"}, {"id": "a292efc5-939a-4131-9a7e-0a91f8a6ff66", "question_key": "ask_resources_credit", "dimension": "resources", "question_text": "Without getting too personal, is your credit strong enough for a traditional bank loan, or would you need other ways to fund a deal?", "follow_up_text": "Have you talked to a lender recently to see where you stand?", "applies_to_stages": null, "priority": 11, "path": "both", "is_active": true, "created_at": "2026-06-10T00:24:08.557193+00:00"}, {"id": "e72271b5-8f80-4f56-8e41-ad5ca28a1442", "question_key": "ask_strategy_general", "dimension": "strategy", "question_text": "Are you looking to invest actively, running deals yourself, or more passively, putting money into deals other people run?", "follow_up_text": "Got it. And which type specifically? Rentals, flipping, wholesaling, short term rentals, or something else?", "applies_to_stages": ["exploring__new", "getting_started"], "priority": 2, "path": "A", "is_active": true, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "7e813377-954f-406e-9b65-9d784d3740ba", "question_key": "ask_blocker_capital", "dimension": "blocker", "question_text": "Are you looking to fund your own deals or raise money from other investors?", "follow_up_text": "Have you looked at private money or hard money options yet?", "applies_to_stages": ["exploring__new", "getting_started", "active_investor", "experienced_investor", "veteran__operator"], "priority": 5, "path": "both", "is_active": false, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "dae33a00-df45-4fe4-b660-f2d2f720d52b", "question_key": "ask_blocker_deals", "dimension": "blocker", "question_text": "When it comes to finding deals, are you struggling with sourcing leads, analyzing them, or making offers?", "follow_up_text": "What have you tried so far to find deals?", "applies_to_stages": ["exploring__new", "getting_started", "active_investor", "experienced_investor", "veteran__operator"], "priority": 6, "path": "both", "is_active": false, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "9a100da1-1b87-4789-a0a3-f309ee9c9cf5", "question_key": "ask_blocker_team", "dimension": "blocker", "question_text": "What part of the team are you missing — contractors, a property manager, a lender, or something else?", "follow_up_text": "Have you worked with anyone in that role before?", "applies_to_stages": ["exploring__new", "getting_started", "active_investor", "experienced_investor", "veteran__operator"], "priority": 7, "path": "both", "is_active": false, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "484d6072-86b7-47d1-b8c6-7338b019a500", "question_key": "ask_readiness", "dimension": "readiness", "question_text": "Would you say you're actively working on making a move right now, still mostly learning, or a bit of both, learning as you go?", "follow_up_text": "What would need to be true for that number to go up?", "applies_to_stages": ["exploring__new", "getting_started"], "priority": 7, "path": "A", "is_active": true, "created_at": "2026-06-02T19:23:03.086521+00:00"}, {"id": "726ec132-14ef-4e4a-a6f5-d386b5fab534", "question_key": "ask_resources_capital", "dimension": "resources", "question_text": "When it comes to capital, do you have funds set aside to invest, or are you starting with little to no money down?", "follow_up_text": "Roughly what range are you working with: under ten thousand, ten to fifty, or more than that?", "applies_to_stages": ["exploring__new", "getting_started", "active_investor", "experienced_investor", "veteran__operator"], "priority": 9, "path": "both", "is_active": true, "created_at": "2026-06-10T00:24:08.557193+00:00"}, {"id": "b97c8b00-0dec-41e4-a5df-c30daaae39b2", "question_key": "ask_resources_time", "dimension": "resources", "question_text": "How much time can you realistically put toward investing each week: just a few hours, ten to twenty, or is this a full-time focus?", "follow_up_text": "Is that likely to change in the next six months?", "applies_to_stages": ["exploring__new", "getting_started", "active_investor", "experienced_investor", "veteran__operator"], "priority": 10, "path": "both", "is_active": true, "created_at": "2026-06-10T00:24:08.557193+00:00"}]$v1snap$);

