-- ===== problem_taxonomy (12 rows) =====
CREATE TABLE IF NOT EXISTS public.problem_taxonomy (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  problem_key text NOT NULL UNIQUE,
  problem_label text NOT NULL,
  match_patterns text[] NOT NULL DEFAULT '{}'::text[],
  complexity_tier text NOT NULL CHECK (complexity_tier = ANY (ARRAY['simple','moderate','complex'])),
  question_budget integer NOT NULL CHECK (question_budget >= 1 AND question_budget <= 5),
  applies_to_paths text[] NOT NULL DEFAULT ARRAY['A','B'],
  round_preface text,
  default_investor_need text,
  default_specialty text,
  default_reia_resource text,
  priority integer DEFAULT 100,
  is_active boolean NOT NULL DEFAULT true,
  notes text,
  created_at timestamptz NOT NULL DEFAULT now()
);
INSERT INTO public.problem_taxonomy
SELECT * FROM json_populate_recordset(NULL::public.problem_taxonomy, $v1snap$[{"id": "2dd22edd-230c-4819-ad4f-3de47666ff9e", "problem_key": "loan_denied", "problem_label": "Loan denied", "match_patterns": ["loan denied", "turned me down", "declined my loan", "cannot get financing", "denied financing", "wont lend"], "complexity_tier": "moderate", "question_budget": 2, "applies_to_paths": ["A", "B"], "round_preface": "Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "funding", "default_specialty": "mortgage_broker", "default_reia_resource": null, "priority": 20, "is_active": true, "notes": "Discriminator is WHO denied them, not why. A bank or credit union lends off its own balance sheet; a broker shops the file. So bank-denied to broker is a good referral, not a loop. Broker-denied means already shopped.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "a086752f-f878-4fb5-a032-bb7b8150b19c", "problem_key": "big_tax_bill", "problem_label": "Big tax bill on a sale", "match_patterns": ["tax bill", "capital gains", "taxes on the sale", "tax hit", "1031"], "complexity_tier": "moderate", "question_budget": 3, "applies_to_paths": ["A", "B"], "round_preface": "Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "funding", "default_specialty": "accountant__tax_specialist", "default_reia_resource": null, "priority": 30, "is_active": true, "notes": "Q3 asks about INTENT, not tax mechanics. Passive vehicles work by different mechanisms (syndication throws passive losses, DST defers, OZ works on gains) and a caller cannot reliably answer whether their liability is active or passive. Lani routes; the advisor determines fit.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "cd9d2f7d-24e3-4505-895e-e98444c1a84d", "problem_key": "no_deal_flow", "problem_label": "Cannot find deals", "match_patterns": ["cannot find deals", "no deal flow", "no inventory", "nothing to buy", "keep losing deals", "outbid"], "complexity_tier": "moderate", "question_budget": 3, "applies_to_paths": ["A", "B"], "round_preface": "Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "deals", "default_specialty": "real_estate_agent", "default_reia_resource": "deal_center", "priority": 40, "is_active": true, "notes": "Deal Center LEADS the brought-to-me branch. Free REIA resource, real current inventory, public. Putting a wholesaler ahead of it would send a member to pay for what the site already gives them.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "a7eef2fa-ecc3-43c3-afd3-9b04033e1225", "problem_key": "str_underperforming", "problem_label": "Short-term rental underperforming", "match_patterns": ["airbnb", "short term rental", "str", "bookings are down", "vrbo"], "complexity_tier": "moderate", "question_budget": 3, "applies_to_paths": ["A", "B"], "round_preface": "Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "operations", "default_specialty": "str_cohost__management_company", "default_reia_resource": null, "priority": 50, "is_active": true, "notes": "Fourth Q1 branch (switching strategy) added by Chris: many owners are moving from short-term to mid-term or co-living. Without it, an owner ready to exit gets handed a cleaning crew. That branch is the only one in the seed set routing to EDUCATION with no vendor.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "a22cdee7-4ecd-4f7b-89e6-9475894d54ab", "problem_key": "land_development_blocked", "problem_label": "Cannot develop the land", "match_patterns": ["perc test", "wont perc", "cannot build", "zoning", "septic", "entitlement", "parcel split"], "complexity_tier": "simple", "question_budget": 1, "applies_to_paths": ["A", "B"], "round_preface": null, "default_investor_need": "development_land", "default_specialty": "civil_engineer", "default_reia_resource": null, "priority": 60, "is_active": true, "notes": "RENAMED and rescoped from land_wont_perc. A failed perc test is septic specifically and reached only 2 of 7 development vendors. The caller blocked on land may be stopped by zoning, wetlands, utilities, an easement or soil.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "2f922145-d3a4-4aa2-bad9-517d32060856", "problem_key": "property_sitting", "problem_label": "Property is not selling", "match_patterns": ["not selling", "sitting on the market", "no offers", "wont sell", "been listed"], "complexity_tier": "moderate", "question_budget": 3, "applies_to_paths": ["A", "B"], "round_preface": "Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "deals", "default_specialty": "real_estate_agent", "default_reia_resource": null, "priority": 70, "is_active": true, "notes": "Chris: the AGENT may be the problem. A newer agent often just puts it on MLS and waits, so a second opinion is a real answer rather than a dead end. Deal Center serves SELLERS here, the mirror of no_deal_flow.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "4f510397-0866-4c40-89fb-12058a23c87d", "problem_key": "insurance_problem", "problem_label": "Insurance cancelled or unaffordable", "match_patterns": ["insurance", "premium went up", "policy cancelled", "cannot get coverage", "uninsurable"], "complexity_tier": "simple", "question_budget": 1, "applies_to_paths": ["A", "B"], "round_preface": null, "default_investor_need": "team", "default_specialty": "insurance", "default_reia_resource": null, "priority": 45, "is_active": true, "notes": "Simple tier despite feeling complex: every insurance situation routes to the same vendor value. WHY coverage lapsed (claims history, roof age, carrier exit) does not change routing. The only real fork is whether a lawyer is also needed. Found by the 12.11 backward enumeration; insurance was unreached by the first 10 problems.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "c555eb01-769f-42bb-9d8e-9ad211cf597b", "problem_key": "vacancy_and_tenant_quality", "problem_label": "Vacancy or bad tenants", "match_patterns": ["cannot fill", "vacant", "vacancy", "bad tenants", "keep getting bad tenants", "no applications"], "complexity_tier": "moderate", "question_budget": 3, "applies_to_paths": ["A", "B"], "round_preface": "Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "operations", "default_specialty": "property_manager", "default_reia_resource": null, "priority": 55, "is_active": true, "notes": "The PREVENTION side of eviction. A caller who has just finished an eviction is a natural candidate for this problem, worth noting for the delivery layer. Found by the 12.11 backward enumeration.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "3af0db5e-7fb1-425f-a98a-2c3952f482a3", "problem_key": "note_in_default", "problem_label": "Note in default", "match_patterns": ["note in default", "borrower stopped paying", "note is in default", "my note", "trust deed", "foreclos"], "complexity_tier": "complex", "question_budget": 5, "applies_to_paths": ["A", "B"], "round_preface": "Okay. Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "legal", "default_specialty": "real_estate_litigation_attorney", "default_reia_resource": null, "priority": 10, "is_active": true, "notes": "ORIGIN of item 12 (Chris test call +18088565351). Scoped to 3 questions, not 5: deficiency exposure was cut as the attorney's job, not Lani's diagnostic. Jurisdiction is asked as LOCATION, not as a judicial-vs-non-judicial legal question the caller may not be able to answer.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "93948124-e725-4551-846f-9b44559b86ba", "problem_key": "eviction", "problem_label": "Tenant not paying / eviction", "match_patterns": ["evict", "tenant not paying", "wont pay rent", "squatter", "behind on rent"], "complexity_tier": "complex", "question_budget": 4, "applies_to_paths": ["A", "B"], "round_preface": "Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "legal", "default_specialty": "landlord__tenant_attorney", "default_reia_resource": null, "priority": 15, "is_active": true, "notes": "Structure MIRRORS note_in_default: outcome first, then responsive-or-not, which either opens a workout path or collapses into enforcement. Chris: a payment-plan conversation does NOT need an attorney. Jurisdiction fires only on the enforcement path.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "5feca4c0-8399-436e-b24f-85fe0db8efc5", "problem_key": "partnerships_and_joint_ventures", "problem_label": "Partnership or joint venture", "match_patterns": ["joint venture", "jv", "partner", "partnership", "split the deal", "syndicate with friends"], "complexity_tier": "complex", "question_budget": 3, "applies_to_paths": ["A", "B"], "round_preface": "Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "legal", "default_specialty": "entity_formation__registered_agent", "default_reia_resource": "true_wealth", "priority": 35, "is_active": true, "notes": "Chris hears this a lot. Failure mode is a badly structured JV, not bad partners, so the entity formation attorney surfaces on the looking-for-partners path too, not only after it goes wrong. NOT sec__securities_attorney: a JV between ACTIVE participants is not a securities offering. The moment a partner is passive it becomes a securities question and a different attorney.", "created_at": "2026-09-22T17:10:37.239579+00:00"}, {"id": "7e9bf1c6-7f42-4c7d-b9fe-68f79139c724", "problem_key": "contractor_abandoned", "problem_label": "Contractor walked off the job", "match_patterns": ["contractor left", "abandoned the job", "contractor disappeared", "unfinished work", "took my deposit"], "complexity_tier": "complex", "question_budget": 4, "applies_to_paths": ["A", "B"], "round_preface": "Let me ask a couple quick things so I point you at the right person.", "default_investor_need": "contractors", "default_specialty": "general_contractor", "default_reia_resource": null, "priority": 25, "is_active": true, "notes": "Q3 (active water or mold damage) sets time-critical ON THE OUTCOME. That case is what drove moving is_time_critical off the problem and onto outcomes.", "created_at": "2026-09-22T17:10:37.239579+00:00"}]$v1snap$);

-- ===== problem_taxonomy_questions (29 rows) =====
CREATE TABLE IF NOT EXISTS public.problem_taxonomy_questions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  problem_key text NOT NULL REFERENCES public.problem_taxonomy(problem_key) ON DELETE CASCADE,
  sequence integer NOT NULL,
  why_preface text,
  question_text text NOT NULL,
  answer_options text[] NOT NULL,
  is_active boolean NOT NULL DEFAULT true,
  notes text,
  UNIQUE (problem_key, sequence)
