SELECT * FROM json_populate_recordset(NULL::public.problem_taxonomy_questions, $v1snap$[{"id": "efe6beac-d19c-427f-b65f-bd74eb78c86e", "problem_key": "note_in_default", "sequence": 1, "why_preface": null, "question_text": "What are you hoping happens here: get the loan back on track, sell the note off, or take the property back?", "answer_options": ["keep", "sell", "possess", "not_sure"], "is_active": true, "notes": null}, {"id": "e0972332-6c7d-47f3-b5e8-f1789d63e1d4", "problem_key": "note_in_default", "sequence": 2, "why_preface": null, "question_text": "Is the borrower still talking to you?", "answer_options": ["responsive", "unresponsive"], "is_active": true, "notes": "Fires on the keep path only. Unresponsive COLLAPSES the goal into enforcement."}, {"id": "b618849d-7183-4f2f-8c1a-10e3007af823", "problem_key": "note_in_default", "sequence": 3, "why_preface": null, "question_text": "Where is the property?", "answer_options": ["utah", "other_state"], "is_active": true, "notes": "SHARED JURISDICTION QUESTION. Resolves judicial vs non-judicial without asking a legal question. No preface needed: investors routinely volunteer where a property is."}, {"id": "e4eb6815-bd1b-4b6c-8895-22bd767c4b77", "problem_key": "big_tax_bill", "sequence": 1, "why_preface": null, "question_text": "Has the sale already closed, or is it still in process?", "answer_options": ["in_process", "closed"], "is_active": true, "notes": "in_process is the only answer in the seed set where delay costs money outright."}, {"id": "0eeaf3f5-a526-4952-aea2-3c2d8ae35e86", "problem_key": "big_tax_bill", "sequence": 2, "why_preface": null, "question_text": "Do you own other investment property you are holding?", "answer_options": ["yes", "no"], "is_active": true, "notes": null}, {"id": "77754ade-b46a-41a1-b262-f56113c54d52", "problem_key": "big_tax_bill", "sequence": 3, "why_preface": null, "question_text": "Would you consider buying another property to offset it, putting money into something passive, or would you rather just talk to a tax specialist?", "answer_options": ["buy_property", "passive_vehicle", "talk_to_specialist", "not_sure"], "is_active": true, "notes": "Added by Chris. Asks INTENT, not tax mechanics."}, {"id": "909eea0b-3fe2-40b7-9a55-5a9db6c4ca3a", "problem_key": "no_deal_flow", "sequence": 1, "why_preface": null, "question_text": "Are you looking to find deals yourself, or have them brought to you?", "answer_options": ["find_myself", "brought_to_me"], "is_active": true, "notes": null}, {"id": "8080cbf2-656f-49da-b770-e1976682b6e6", "problem_key": "no_deal_flow", "sequence": 2, "why_preface": null, "question_text": "Are you finding properties and losing them, or not finding much to look at?", "answer_options": ["losing_them", "not_finding"], "is_active": true, "notes": "Losing deals and not finding deals are different problems. The first draft missed this."}, {"id": "6381086a-b823-4cb4-8ca0-4e8f227dd2e6", "problem_key": "no_deal_flow", "sequence": 3, "why_preface": null, "question_text": "Losing on price, or on speed? And if you are still looking, do you have a list and marketing running, or nothing yet?", "answer_options": ["price", "speed", "has_list", "no_list"], "is_active": true, "notes": "Enum renamed from \"scratch\" to no_list: enum values are read by people who were not in the design conversation."}, {"id": "231e3fbd-e606-4eab-aefd-7b4810e2b79e", "problem_key": "str_underperforming", "sequence": 1, "why_preface": null, "question_text": "What is the main issue: bookings are down, the day to day is wearing you out, the city changed the rules, or are you thinking about switching it to something else?", "answer_options": ["bookings_down", "operations_burden", "regulations", "switching_strategy"], "is_active": true, "notes": "Four answers is at the upper limit for a voice question. If it tests poorly, split Q1 into performance-vs-direction. Build it FLAT first."}, {"id": "c923891d-c27c-4caf-8f1c-6b01896a3b13", "problem_key": "str_underperforming", "sequence": 2, "why_preface": null, "question_text": "Is the listing not getting views, or do people look and not book? Or is it the turnovers and cleaning versus the guest side? Or are you thinking mid-term and co-living, or a straight long-term rental?", "answer_options": ["not_getting_views", "look_dont_book", "cleaning_turnover", "guest_management", "midterm_coliving", "long_term", "not_sure"], "is_active": true, "notes": "Branch-dependent Q2. midterm__coliving_rentals is a SINGLE Educational Topic value, so mid-term and co-living are one branch."}, {"id": "99168dd3-2bf1-4771-a22a-6665c77cd67a", "problem_key": "land_development_blocked", "sequence": 1, "why_preface": null, "question_text": "What is holding it up: the soil or septic side, zoning and permitting, something about access and utilities, or splitting the parcel?", "answer_options": ["soil_septic", "zoning_permitting", "access_utilities", "parcel_split", "not_sure"], "is_active": true, "notes": "parcel_split added by Chris: surveyors come up for separating parcels and entitlement work."}, {"id": "f3f1d362-9685-4899-980e-a21c6ef94077", "problem_key": "property_sitting", "sequence": 1, "why_preface": null, "question_text": "Are you getting showings but no offers, or not much traffic at all?", "answer_options": ["showings_no_offers", "no_traffic"], "is_active": true, "notes": null}, {"id": "6d265b5b-1a94-455c-b78a-75a96ba1f34b", "problem_key": "property_sitting", "sequence": 2, "why_preface": null, "question_text": "Is it listed with an agent, or are you selling it yourself?", "answer_options": ["with_agent", "fsbo"], "is_active": true, "notes": null}, {"id": "a598d5f5-18a1-46c0-8c76-9b6c9e24d0d9", "problem_key": "property_sitting", "sequence": 3, "why_preface": null, "question_text": "Would you be open to selling to an investor instead?", "answer_options": ["yes", "no"], "is_active": true, "notes": null}, {"id": "c358a23f-02b8-42ef-bc7e-76a9124c592b", "problem_key": "eviction", "sequence": 1, "why_preface": null, "question_text": "What are you hoping for, get them paying again, or get them out?", "answer_options": ["paying_again", "get_them_out"], "is_active": true, "notes": null}, {"id": "d4a22027-8df4-4185-9a4a-bd373f45f99e", "problem_key": "eviction", "sequence": 2, "why_preface": null, "question_text": "Is the tenant still talking to you?", "answer_options": ["responsive", "unresponsive"], "is_active": true, "notes": "Fires on the paying_again path. Unresponsive collapses into get_them_out, mirroring note_in_default."}, {"id": "81c72bea-cce3-4543-9598-2c9d56b65c62", "problem_key": "eviction", "sequence": 3, "why_preface": null, "question_text": "Where is the property?", "answer_options": ["utah", "other_state"], "is_active": true, "notes": "SHARED JURISDICTION QUESTION. Fires only on the enforcement path; a payment plan is not jurisdiction-specific."}, {"id": "8efbc3f1-338c-4dea-bf58-d99551815170", "problem_key": "eviction", "sequence": 4, "why_preface": null, "question_text": "Are you managing it yourself, or do you have a property manager?", "answer_options": ["self_managing", "has_manager"], "is_active": true, "notes": null}, {"id": "8822d803-25ac-4f29-9385-613920f8dca2", "problem_key": "contractor_abandoned", "sequence": 1, "why_preface": null, "question_text": "What do you need most right now, someone to finish the work, or to go after the contractor?", "answer_options": ["finish", "go_after", "both"], "is_active": true, "notes": null}, {"id": "42af03b8-a6cf-4677-9c07-7b8ab2ea7b33", "problem_key": "contractor_abandoned", "sequence": 2, "why_preface": null, "question_text": "What kind of work is left?", "answer_options": ["general", "electrical", "plumbing", "hvac", "roofing", "flooring", "drywall", "painting", "framing", "concrete", "landscaping", "other"], "is_active": true, "notes": "Maps to contractor_specility. NOTE THE LOCKED SPELLING: misspelled in GHL, immutable, correct as written."}, {"id": "f8b5df13-0ed2-452c-8bf1-8d57d4e0dc4e", "problem_key": "contractor_abandoned", "sequence": 3, "why_preface": null, "question_text": "Is there active water or mold damage?", "answer_options": ["yes", "no"], "is_active": true, "notes": "YES sets time-critical ON THE OUTCOME. Damage spreads daily."}, {"id": "b7eca785-211b-4186-b0ee-f858f1f55494", "problem_key": "partnerships_and_joint_ventures", "sequence": 1, "why_preface": null, "question_text": "Are you setting one up, dealing with one that has gone sideways, or looking for partners?", "answer_options": ["setting_up", "gone_sideways", "looking_for_partners"], "is_active": true, "notes": null}, {"id": "3234cf32-3674-44f4-9ac9-4b81d085731f", "problem_key": "partnerships_and_joint_ventures", "sequence": 2, "why_preface": null, "question_text": "Do you have a deal and need capital, or capital and want into deals?", "answer_options": ["deal_need_capital", "capital_want_deals"], "is_active": true, "notes": "Both route to True Wealth TODAY. The split exists because the future member-run club build (item 51) serves the two sides differently. Do not simplify it away."}, {"id": "bd5a8557-42be-4460-9ea2-8f1dad069e59", "problem_key": "insurance_problem", "sequence": 1, "why_preface": null, "question_text": "Is this about getting or keeping coverage, or is it a claim they have denied?", "answer_options": ["coverage", "denied_claim"], "is_active": true, "notes": null}, {"id": "50c0b74c-c3f8-477c-99cd-fc6235870809", "problem_key": "vacancy_and_tenant_quality", "sequence": 1, "why_preface": null, "question_text": "Is the unit sitting empty, are you getting bad tenants, or are you just tired of handling it?", "answer_options": ["sitting_empty", "bad_tenants", "tired_of_handling"], "is_active": true, "notes": null}, {"id": "3304c3c3-4ecf-42db-8e0f-b61e85463afe", "problem_key": "vacancy_and_tenant_quality", "sequence": 2, "why_preface": null, "question_text": "Is it getting views but no applications, or not much interest at all?", "answer_options": ["views_no_applications", "no_interest"], "is_active": true, "notes": null}, {"id": "80d2755c-fae6-4406-a7d2-73e6819f1aab", "problem_key": "loan_denied", "sequence": 1, "why_preface": null, "question_text": "Are you flipping this one or holding it?", "answer_options": ["flip", "hold", "not_sure"], "is_active": true, "notes": "Reordered 2026-09-24. Strategy first, because it determines the loan PRODUCT. Who denied them only changes routing on the hold branch."}, {"id": "60b7eca1-b4fc-418e-aacf-14729f2fecbe", "problem_key": "loan_denied", "sequence": 2, "why_preface": null, "question_text": "Who turned you down, a bank or credit union, or a mortgage broker?", "answer_options": ["bank_or_credit_union", "mortgage_broker", "not_sure"], "is_active": true, "notes": "Fires on the HOLD branch only. A bank lends off its own balance sheet; a broker shops the file. So bank-denied means DSCR has probably not been tried. Broker-denied means it has."}]$v1snap$);

