CREATE TABLE IF NOT EXISTS public.problem_taxonomy_outcomes (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  problem_key text NOT NULL REFERENCES public.problem_taxonomy(problem_key) ON DELETE CASCADE,
  question_sequence integer NOT NULL,
  answer_value text NOT NULL,
  rank integer NOT NULL DEFAULT 1,
  investor_need text,
  specialty text,
  strategy text,
  education_topic text,
  reia_resource_key text,
  next_question_sequence integer,
  is_terminal boolean NOT NULL DEFAULT false,
  is_time_critical boolean NOT NULL DEFAULT false,
  confidence text NOT NULL DEFAULT 'exact' CHECK (confidence = ANY (ARRAY['exact','close'])),
  is_active boolean NOT NULL DEFAULT true,
  notes text
);
